--
-- Table structure for table `chat_url`
--

DROP TABLE IF EXISTS `chat_url`;
CREATE TABLE `chat_url` (
  `id` bigint(20) NOT NULL auto_increment,
  `url` text NOT NULL,
  `title` text,
  `description` text,
  `votes` int(11) NOT NULL default '0',
  `average_rating` float NOT NULL default '0',
  `creation_date` datetime NOT NULL default '0000-00-00 00:00:00',
  `tags` text,
  PRIMARY KEY  (`id`),
  UNIQUE KEY `url` (`url`(1000)),
  KEY `chat_url_creation_date_idx` (`creation_date`),
  FULLTEXT KEY `title` (`title`,`description`),
  FULLTEXT KEY `tags` (`tags`)
) ENGINE=MyISAM AUTO_INCREMENT=351 DEFAULT CHARSET=latin1;

